    // Publications: publications.
    'publications.publications': 'Signierte Einträge',
    'publications.whatThisIs': 'Signierte Einträge Ihrer Arbeit, die zwischen Geräten und Netzwerken reisen können: Bauwerke, die Sie mit „Mit Peers teilen“ geteilt haben, Strukturen, die Sie entworfen, und Orte, die Sie benannt haben. Ihre Bauwerke selbst finden Sie auf {yourPage} und unter {explore}.',
    'publications.whatThisIsNoName': 'Signierte Einträge von Arbeiten, die zwischen Geräten und Netzwerken reisen können: mit „Mit Peers teilen“ geteilte Bauwerke, entworfene Strukturen und benannte Orte. Die Bauwerke selbst finden Sie unter {explore}.',
    'publications.yourPage': 'Ihrer Seite',
    'publications.intro': 'Jeder signierte Eintrag, den dieses Gerät gesehen hat — ein eigener oder einer, den ein verbundener {peer} angekündigt hat. Jeder Status wird beim Öffnen der Seite neu geprüft: In der Liste zu stehen bedeutet nie, dass der Inhalt auf diesem Gerät ist. Wallet- und Archivwerkzeuge finden Sie unter {tools} unten auf der Seite.',
    'publications.introToolsHidden': 'Jeder signierte Eintrag, den dieses Gerät gesehen hat — ein eigener oder einer, den ein verbundener {peer} angekündigt hat. Jeder Status wird beim Öffnen der Seite neu geprüft: In der Liste zu stehen bedeutet nie, dass der Inhalt auf diesem Gerät ist. Experimentelle Wallet- und Archivwerkzeuge sind ausgeblendet; schalten Sie unter {settings} „Experimentelle Werkzeuge anzeigen“ ein, um sie aufzulisten.',
    'publications.peer': 'Peer',
    'publications.walletArchiveTools': 'Wallet- & Archivwerkzeuge',
    'publications.walletsSwitchedOn': 'Die Bitcoin- und Base-Wallets erscheinen hier, sobald sie unter {settings} eingeschaltet sind.',
    'publications.partsMarked': 'Mit {badge} gekennzeichnete Teile (Verankerung, Wallets, Steem, Blurt, entferntes IPFS-Pinning sowie die Wallet- und Archivwerkzeuge) funktionieren, können sich aber in einer späteren Version ändern oder entfernt werden, und was sie erzeugen, wird möglicherweise nicht übernommen.',
    'publications.experimental': 'Experimentell',
    'publications.peers': 'Peers',
    'publications.checkingCatalogedPublications': 'Erfasste Einträge werden geprüft …',
    'publications.nothingCatalogedYetPublishA': 'Noch nichts erfasst. Veröffentlichen Sie einen signierten Zuschreibungs- oder Namensanspruch oder verbinden Sie sich mit einem Peer, der einen hat, dann erscheint er hier.',
    'publications.noneOfTheCatalogedPublications': 'Keiner der erfassten Einträge hat seine Prüfung bestanden; sie sind unten aufgeführt.',
    'publications.details': 'Details',
    'publications.snapshot': 'Snapshot',
    'publications.decentralizationEvidence': 'Dezentralisierung & Nachweise',
    'publications.placementsIpfs': 'Platzierungen & IPFS',
    'publications.history': 'Verlauf',
    'publications.crossDomainObservationTimeline': 'Domänenübergreifende Beobachtungszeitleiste',
    'publications.historyHint': 'Jede IPFS-, Bitcoin- und Base-Beobachtung, die dieses Gerät zu diesem Eintrag aufgezeichnet hat, die älteste zuerst, über Besuche hinweg aufbewahrt. Jede behält die Begriffe ihres eigenen Netzwerks; keine ist ein zusammengefasster Status.',
    'publications.historyEmpty': 'Zu diesem Eintrag ist noch nichts aufgezeichnet. Das Veröffentlichen auf entferntem IPFS oder das Senden oder Prüfen eines Bitcoin- oder Base-Ankers dafür ergänzt diese Liste.',
    'publications.historySources': 'Entferntes IPFS-Pinning sowie die Verankerung auf Bitcoin und Base, die diese Liste ergänzen, sind experimentell.',
    'publications.theseFailedTheirCheckSo': 'Diese haben ihre Prüfung nicht bestanden und können daher nicht geöffnet, verteilt oder verankert werden. Bei jedem steht, warum; einer, der mit einem alten Inhalts-Hash veröffentlicht wurde, muss von seinem Autor erneut veröffentlicht werden. Das Entfernen vergisst ihn nur auf diesem Gerät; ein Peer, der ihn noch hat, kann ihn erneut ankündigen.',
    'publications.removeIsSafe': 'Das Entfernen eines Eintrags berührt nie Ihre Bauwerke: Sie bleiben im Editor, unter „Entdecken“ und unter {myBuilds}. Nur dieser signierte Eintrag wird vergessen, und zwar auf diesem Gerät.',
    'publications.removeIsSafeNoName': 'Das Entfernen eines Eintrags berührt nie Ihre Bauwerke: Sie bleiben im Editor und unter „Entdecken“. Nur dieser signierte Eintrag wird vergessen, und zwar auf diesem Gerät.',
