    'publications.verificationFinalization': 'Überprüfung & Finalisierung',
    'publications.finalizingIndependentlyCryptographicallyVerifiesThe': 'Das Finalisieren überprüft die signierte Transaktion unabhängig und kryptografisch gegen genau den oben geprüften Plan — einschließlich der Ermittlung des tatsächlichen Unterzeichners aus der Signatur selbst. Es sendet sie nicht.',
