    // Identity, Peers, Chat and settings: announcementDiscoveryProviderSettingsView.
    'announcementDiscoveryProviderSettingsView.announcementDiscoveryProvider': 'Anbieter für Ankündigung / Entdeckung',
    'announcementDiscoveryProviderSettingsView.chooseTheDefaultDecentralizedSubstrate': 'Wählen Sie das standardmäßige dezentrale Substrat — Nostr, Arweave, Steem oder Blurt —, auf dem Ihre signierten Einträge (Geteilte Welten, Bauplan-Zuschreibungen und Ortsnamen), Snapshots und Kommentare angekündigt werden. Eine Seite oder ein Bedienelement mit eigener ausdrücklicher Auswahl überschreibt diesen Standard weiterhin für diese eine Aktion.',
    'announcementDiscoveryProviderSettingsView.thisChoiceNeverNarrowsDiscovery': 'Diese Wahl schränkt die Entdeckung nie ein: Die Suche nach Inhalten anderer Personen durchsucht immer Nostr, Arweave, Steem und Blurt gemeinsam.',
    'announcementDiscoveryProviderSettingsView.savingHereTakesEffectThe': 'Das Speichern hier wirkt beim nächsten Laden dieser App — es ändert nie eine bereits laufende Ankündigung.',
    'announcementDiscoveryProviderSettingsView.saved': 'Gespeichert.',
