    'blurtSettingsView.whereThisReplicaReadsBlurt': 'Woher diese Replik Blurt-Beiträge liest: signierte Einträge (Geteilte Welten, Bauplan-Zuschreibungen und Ortsnamen), Snapshots und Kommentare, die Personen von ihren eigenen Konten als Hauptbeiträge mit dem Tag forkbuild veröffentlichen. Sie werden über Nexus gelesen, den Indexer von Blurt, der jeden Beitrag unter dem Tag listet, egal wie alt; ein Knoten ohne Nexus wird übersprungen. Hat kein Knoten Nexus, listet der Tag einen Beitrag nur, bis er nach sieben Tagen ausgezahlt wird, und ältere Beiträge werden aus den Verläufen der Konten gelesen, die dieses Gerät posten sah. Jede Ankündigung wird vor der Verwendung geprüft. Zum Lesen ist kein Blurt-Konto nötig. Änderungen gelten ab dem nächsten Laden der App.',
